  function addSelfBank(courseId, topicId, index, questions) {
    var key = "self_" + topicId + "_" + index;
    var bank = window.EXTRA_TESTS[key] || (window.EXTRA_TESTS[key] = { questions: [] });
    if (!Array.isArray(bank.questions)) bank.questions = [];
    questions.forEach(function (q) {
      if (!bank.questions.some(function (old) { return old.q === q.q; })) bank.questions.push(q);
    });
  }

  function addExamBank(id, questions) {
    var key = "EXAM_BANK_" + id.replace(".", "");
    var current = window[key] || window.EXTRA_EXAM_BANKS[id] || [];
    var merged = current.slice();
    questions.forEach(function (q) {
      if (!merged.some(function (old) { return old.q === q.q; })) merged.push(q);
    });
    window[key] = merged;
    window.EXTRA_EXAM_BANKS[id] = merged;
  }

